#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""calculator.py —— 一个可以直接在本地运行的命令行计算器（纯标准库，无第三方依赖）。

用法
----
    python3 calculator.py                 # 进入交互模式，敲算式回车即算
    python3 calculator.py "2+3*4"         # 直接算一个算式并打印结果
    python3 calculator.py --help          # 查看帮助

支持的写法
----------
    四则运算     +  -  *  /      （自动处理优先级）
    括号         (  )            可以嵌套
    百分号       %               50% 等于 0.5
    正负号       -3 + 5 、 2*-3  （一元负号）
    隐式乘法     2(3+4) 等于 14 、 3ans
    上一次结果   ans             交互模式下引用上一次算出的值
    全角符号     ＋ － × ÷ （ ） ％  会自动转换成半角，中文输入法下也能直接敲

交互模式下额外命令
------------------
    help / ?     查看帮助         q / quit / exit   退出
    ac / clear   清空 ans 记录

精度说明
--------
内部用 Fraction（有理数）做精确计算，所以 0.1+0.2 得到 0.3、
(1/3)*3 得到 1，不会出现浮点误差。只有当结果无法写成有限小数时
（例如 1/3），才四舍五入保留 11 位小数显示。
"""

from __future__ import annotations

import sys
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from fractions import Fraction


class CalcError(Exception):
    """算式本身的问题（语法错误、除以 0 等），消息可以直接展示给用户。"""


# --------------------------------------------------------------------------
# 词法分析
# --------------------------------------------------------------------------

# 中文输入法常打出来的全角符号，统一折成半角再解析
_FULLWIDTH = str.maketrans({
    "＋": "+", "－": "-", "−": "-", "–": "-", "—": "-",
    "×": "*", "＊": "*", "÷": "/", "／": "/",
    "（": "(", "）": ")", "％": "%", "　": " ", "．": ".",
})

_OPS = "+-*/"
_PREC = {"+": 1, "-": 1, "*": 2, "/": 2}
_UNARY_PREC = 3          # 一元负号的优先级，最高


def tokenize(text: str):
    """把字符串切成词法单元：('num', 文本) / ('ans',) / ('+',) / ('(',) / ('pct',) 等。"""
    text = text.translate(_FULLWIDTH)
    tokens = []
    i, n = 0, len(text)

    while i < n:
        ch = text[i]

        if ch.isspace():
            i += 1
            continue

        # 数字：允许 .5、5.、3.14
        if ch.isdigit() or ch == ".":
            j, dots = i, 0
            while j < n and (text[j].isdigit() or text[j] == "."):
                if text[j] == ".":
                    dots += 1
                    if dots > 1:
                        raise CalcError("小数点写多了：%s" % text[i:j + 1])
                j += 1
            lit = text[i:j]
            if lit == ".":
                raise CalcError("只有一个孤零零的小数点，缺少数字")
            tokens.append(("num", lit))
            i = j
            continue

        if ch in _OPS or ch in "()":
            tokens.append((ch,))
            i += 1
            continue

        if ch == "%":
            tokens.append(("pct",))
            i += 1
            continue

        # 字母：目前只认识 ans
        if ch.isalpha() or ch == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            word = text[i:j]
            if word.lower() == "ans":
                tokens.append(("ans",))
            else:
                raise CalcError("看不懂这个名字：%s（这里只支持 ans 表示上一次结果）" % word)
            i = j
            continue

        raise CalcError("看不懂的符号：%s" % ch)

    return tokens


# --------------------------------------------------------------------------
# 语法整理：去掉末尾悬空的运算符、补全漏写的右括号
# --------------------------------------------------------------------------

def tidy(tokens):
    tokens = list(tokens)

    # "2+3*" 这种末尾多敲的运算符直接忽略（跟手机计算器的习惯一致）
    while tokens and (tokens[-1][0] in _OPS or tokens[-1][0] == "("):
        tokens.pop()

    # 漏写的右括号自动补上；多写的右括号报错
    depth = 0
    for tok in tokens:
        if tok[0] == "(":
            depth += 1
        elif tok[0] == ")":
            depth -= 1
            if depth < 0:
                raise CalcError("右括号比左括号多，括号不匹配")
    tokens.extend([(")",)] * depth)

    return tokens


# --------------------------------------------------------------------------
# 中缀表达式 -> 逆波兰表达式（调度场算法）
# --------------------------------------------------------------------------

def _push_binary(op, output, stack):
    """把一个二元运算符入栈：先弹出所有优先级不低于它的栈顶运算符（左结合）。"""
    while stack:
        top = stack[-1][0]
        if top == "(":
            break
        top_prec = _UNARY_PREC if top == "u-" else _PREC[top]
        if top_prec < _PREC[op]:
            break
        output.append(stack.pop())
    stack.append((op,))


def to_rpn(tokens):
    if not tokens:
        raise CalcError("没有算式可以计算")

    output = []
    stack = []
    expect_operand = True      # True 表示下一个单元应该是数字/括号，而不是运算符

    for tok in tokens:
        kind = tok[0]

        if kind in ("num", "ans"):
            if not expect_operand:
                _push_binary("*", output, stack)   # 隐式乘法：2(3+4)、3ans
            output.append(tok)
            expect_operand = False

        elif kind in _OPS:
            if expect_operand:
                if kind == "-":
                    stack.append(("u-",))          # 一元负号
                elif kind == "+":
                    pass                           # 一元正号，直接忽略
                else:
                    raise CalcError("运算符 %s 前面缺少数字" % kind)
            else:
                _push_binary(kind, output, stack)
                expect_operand = True

        elif kind == "(":
            if not expect_operand:
                _push_binary("*", output, stack)   # 2(3+4)
            stack.append(("(",))
            expect_operand = True

        elif kind == ")":
            if expect_operand:
                raise CalcError("右括号前面缺少数字")
            while stack and stack[-1][0] != "(":
                output.append(stack.pop())
            if not stack:
                raise CalcError("括号不匹配")
            stack.pop()                            # 弹出 '('
            expect_operand = False

        elif kind == "pct":
            if expect_operand:
                raise CalcError("百分号前面缺少数字")
            output.append(("pct",))                # 后缀运算，直接进输出队列
            expect_operand = False

        else:
            raise CalcError("内部错误：未知词法单元 %r" % (tok,))

    while stack:
        top = stack.pop()
        if top[0] == "(":
            raise CalcError("左括号没有闭合")
        output.append(top)

    return output


# --------------------------------------------------------------------------
# 计算逆波兰表达式（不需要 eval）
# --------------------------------------------------------------------------

def eval_rpn(rpn, ans=None):
    stack = []

    for tok in rpn:
        kind = tok[0]

        if kind == "num":
            try:
                stack.append(Fraction(tok[1]))
            except (ValueError, ZeroDivisionError):
                raise CalcError("数字写法有问题：%s" % tok[1])

        elif kind == "ans":
            if ans is None:
                raise CalcError("还没有算过结果，ans 现在没有值")
            stack.append(ans)

        elif kind == "u-":
            if not stack:
                raise CalcError("负号后面缺少数字")
            stack.append(-stack.pop())

        elif kind == "pct":
            if not stack:
                raise CalcError("百分号前面缺少数字")
            stack.append(stack.pop() / 100)

        else:                                      # 二元运算符
            if len(stack) < 2:
                raise CalcError("运算符 %s 缺少操作数，请检查算式" % kind)
            b = stack.pop()
            a = stack.pop()
            if kind == "+":
                stack.append(a + b)
            elif kind == "-":
                stack.append(a - b)
            elif kind == "*":
                stack.append(a * b)
            else:
                if b == 0:
                    raise CalcError("不能除以 0")
                stack.append(a / b)

    if len(stack) != 1:
        raise CalcError("算式不完整，请检查运算符和括号")
    return stack[0]


# --------------------------------------------------------------------------
# 对外接口
# --------------------------------------------------------------------------

def calculate(expression: str, ans: Fraction | None = None) -> Fraction:
    """算一个算式，返回精确的 Fraction 结果。出错抛 CalcError。"""
    tokens = tokenize(expression)
    if not tokens:
        raise CalcError("没有算式可以计算")
    tokens = tidy(tokens)
    if not tokens:
        raise CalcError("没有算式可以计算")
    return eval_rpn(to_rpn(tokens), ans)


def format_number(value: Fraction) -> str:
    """把 Fraction 变成好看的十进制字符串。"""
    if value.denominator == 1:
        return str(value.numerator)

    # 分母去掉所有 2 和 5 之后还剩 1，说明能写成有限小数
    rest = value.denominator
    while rest % 2 == 0:
        rest //= 2
    while rest % 5 == 0:
        rest //= 5

    try:
        with localcontext() as ctx:
            ctx.prec = 50
            dec = Decimal(value.numerator) / Decimal(value.denominator)
            if rest != 1:      # 无限循环小数，四舍五入到 11 位小数
                dec = dec.quantize(Decimal("1.00000000000"), rounding=ROUND_HALF_UP)
            text = format(dec, "f").rstrip("0").rstrip(".")
    except (InvalidOperation, ValueError):
        return repr(float(value))

    return text if text not in ("", "-", "-0") else "0"


HELP_TEXT = """\
可以这样写：
  1+2*3            普通四则运算，乘除优先
  (1+2)*3          括号可以嵌套
  50%              百分号，50% 就是 0.5
  200*10%          等于 20
  -3+5             一元负号，也可以写 2*-3
  2(3+4)           省略乘号，等于 14
  ans*2            用上一次的结果继续算
  0.1+0.2          得到 0.3（不是 0.30000000000000004）

命令：
  help / ?         显示这份帮助
  ac / clear       清空 ans 记录
  q / quit / exit  退出
  Ctrl+C / Ctrl+D  退出"""

BANNER = """\
========================================
  命令行计算器   输入算式回车即算
  输入 help 看用法，输入 q 退出
========================================"""


def repl() -> int:
    print(BANNER)
    ans = None
    while True:
        try:
            line = input(">>> ")
        except (EOFError, KeyboardInterrupt):
            print()
            break

        line = line.strip()
        if not line:
            continue

        low = line.lower()
        if low in ("q", "quit", "exit", "bye", "退出"):
            break
        if low in ("h", "help", "?", "帮助"):
            print(HELP_TEXT)
            continue
        if low in ("ac", "clear", "cls", "清空"):
            ans = None
            print("已清空记录。")
            continue

        try:
            value = calculate(line, ans)
        except CalcError as exc:
            print("✗ %s" % exc)
            continue

        ans = value
        print("= %s" % format_number(value))

    print("再见。")
    return 0


def main(argv) -> int:
    args = [a for a in argv[1:]]

    if any(a in ("-h", "--help", "/?", "help") for a in args):
        print(HELP_TEXT)
        return 0

    if args:
        expression = " ".join(args)
        try:
            value = calculate(expression)
        except CalcError as exc:
            print("✗ %s" % exc, file=sys.stderr)
            return 1
        print(format_number(value))
        return 0

    return repl()


if __name__ == "__main__":
    sys.exit(main(sys.argv))

